"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-alert-dialog";
import { useFlowAppearance } from "@/lib/cojeev-motion/use-flow";
import { Button } from "@/components/ui/button";
export type AlertDialogProps = React.ComponentProps<typeof Primitive.Root>;
export function AlertDialog(props: AlertDialogProps) {
  return <Primitive.Root {...props} />;
}
export type AlertDialogTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
>;
export function AlertDialogTrigger(props: AlertDialogTriggerProps) {
  return (
    <Primitive.Trigger
      data-slot="alert-dialog-trigger"
      data-part="trigger"
      data-dialog-open=""
      {...props}
    />
  );
}
export type AlertDialogPortalProps = React.ComponentProps<
  typeof Primitive.Portal
>;
export function AlertDialogPortal(props: AlertDialogPortalProps) {
  return <Primitive.Portal {...props} />;
}
export type AlertDialogOverlayProps = React.ComponentProps<
  typeof Primitive.Overlay
>;
export function AlertDialogOverlay({
  className,
  ref,
  ...props
}: AlertDialogOverlayProps) {
  const flowRef = useFlowAppearance<HTMLDivElement>(true, ref, "fade");
  return (
    <Primitive.Overlay
      ref={flowRef}
      data-slot="alert-dialog-overlay"
      data-part="overlay"
      className={cn(
        "v-scrim fixed inset-0 bg-[var(--v-scrim)] z-[calc(var(--z-dialog)-1)]",
        className,
      )}
      {...props}
    />
  );
}
export const alertdialogContentVariants = cva(
  "v-dialog [position:fixed] [inset:0] [margin:auto] [width:min(520px,calc(100%_-_48px))] [height:fit-content] [background:var(--v-canvas)] [border-radius:var(--r-sheet)] [padding:var(--s-8)] [z-index:var(--z-dialog)] [display:grid] [box-shadow:var(--shadow-float),inset_0_0_0_1px_var(--v-border)] [gap:var(--s-4)]",
);
export type AlertDialogContentProps = React.ComponentProps<
  typeof Primitive.Content
> & { showCloseButton?: boolean };
export function AlertDialogContent({
  className,
  ref,
  children,
  showCloseButton = false,
  ...props
}: AlertDialogContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const flowRef = useFlowAppearance<HTMLDivElement>(true, morphRef, "enter");
  return (
    <Primitive.Portal>
      <AlertDialogOverlay />
      <Primitive.Content
        ref={flowRef}
        data-slot="alert-dialog-content"
        data-part="content"
        className={cn(alertdialogContentVariants(), className)}
        {...props}
      >
        {children}
        {showCloseButton && (
          <AlertDialogCancel
            aria-label="Close"
            className="absolute right-4 top-4"
          >
            ×
          </AlertDialogCancel>
        )}
      </Primitive.Content>
    </Primitive.Portal>
  );
}
export type AlertDialogHeaderProps = React.ComponentProps<"div">;
export function AlertDialogHeader({
  className,
  ...props
}: AlertDialogHeaderProps) {
  return (
    <div
      data-slot="alert-dialog-header"
      data-part="header"
      className={cn(
        "v-dialog__head flex items-start justify-between gap-[var(--s-4)]",
        className,
      )}
      {...props}
    />
  );
}
export type AlertDialogFooterProps = React.ComponentProps<"div">;
export function AlertDialogFooter({
  className,
  ...props
}: AlertDialogFooterProps) {
  return (
    <div
      data-slot="alert-dialog-footer"
      data-part="footer"
      className={cn(
        "v-dialog__actions flex gap-[var(--s-3)] justify-end mt-[var(--s-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type AlertDialogTitleProps = React.ComponentProps<
  typeof Primitive.Title
>;
export function AlertDialogTitle({
  className,
  ...props
}: AlertDialogTitleProps) {
  return (
    <Primitive.Title
      data-slot="alert-dialog-title"
      data-part="title"
      className={cn(
        "v-section font-[family-name:var(--font-display)] text-[24px] leading-[1.15] tracking-[-0.01em] pt-1.5 font-medium",
        className,
      )}
      {...props}
    />
  );
}
export type AlertDialogDescriptionProps = React.ComponentProps<
  typeof Primitive.Description
>;
export function AlertDialogDescription({
  className,
  ...props
}: AlertDialogDescriptionProps) {
  return (
    <Primitive.Description
      data-slot="alert-dialog-description"
      data-part="description"
      className={cn(
        "v-body-2 text-[15px] leading-[1.5] text-[color:var(--v-text-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type AlertDialogActionProps = React.ComponentProps<
  typeof Primitive.Action
>;
export function AlertDialogAction({
  asChild,
  children,
  ...props
}: AlertDialogActionProps) {
  return (
    <Primitive.Action
      data-slot="alert-dialog-action"
      data-part="action"
      asChild
      {...props}
    >
      {asChild ? children : <Button variant="danger">{children}</Button>}
    </Primitive.Action>
  );
}
export type AlertDialogCancelProps = React.ComponentProps<
  typeof Primitive.Cancel
>;
export function AlertDialogCancel({
  asChild,
  children,
  ...props
}: AlertDialogCancelProps) {
  return (
    <Primitive.Cancel
      data-slot="alert-dialog-cancel"
      data-part="action"
      asChild
      {...props}
    >
      {asChild ? children : <Button variant="secondary">{children}</Button>}
    </Primitive.Cancel>
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-scrim:where([data-slot="alert-dialog"], [data-slot^="alert-dialog-"]) {
  position: fixed;
  inset: 0;
  background: var(--v-scrim);
  z-index: var(--z-sheet);
}
.v-dialog__head:where(
  [data-slot="alert-dialog"],
  [data-slot^="alert-dialog-"]
) {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-4);
}
.v-dialog__actions:where(
  [data-slot="alert-dialog"],
  [data-slot^="alert-dialog-"]
) {
  display: flex;
  gap: var(--s-2);
  justify-content: flex-end;
}
/* Scrim paint and retained close use the shared opacity-only Motion lane. */
.v-dialog:where([data-slot="alert-dialog"], [data-slot^="alert-dialog-"]) {
  animation: v-dialog-in var(--t-max) var(--enter) both;
}
.v-dialog__head:where(
  [data-slot="alert-dialog"],
  [data-slot^="alert-dialog-"]
) {
  align-items: start;
}
.v-dialog__head:where([data-slot="alert-dialog"], [data-slot^="alert-dialog-"])
  .v-section {
  font-size: 24px;
  line-height: 1.15;
  padding-top: 6px;
}
.v-dialog:where([data-slot="alert-dialog"], [data-slot^="alert-dialog-"])
  > .v-body-2 {
  max-width: 52ch;
}
.v-dialog__actions:where(
  [data-slot="alert-dialog"],
  [data-slot^="alert-dialog-"]
) {
  margin-top: var(--s-2);
  gap: var(--s-3);
}
.v-dialog:where([data-slot="alert-dialog"], [data-slot^="alert-dialog-"]) {
  scrollbar-gutter: stable;
}
.v-dialog:where([data-slot="alert-dialog"], [data-slot^="alert-dialog-"]) {
  scrollbar-gutter: stable;
}
@keyframes v-scrim-in {
  from {
    opacity: 0;
  }
}
@keyframes v-dialog-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.985);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="alert-dialog"],
  [data-slot^="alert-dialog-"],
  [data-slot="alert-dialog"]::before,
  [data-slot="alert-dialog"]::after,
  [data-slot^="alert-dialog-"]::before,
  [data-slot^="alert-dialog-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}


/* A long dialog stays inside the screen; its actions remain reachable. */
[data-slot="alert-dialog-content"] { max-height:calc(100dvh - 32px); overflow-y:auto; overscroll-behavior:contain; min-width:0; grid-template-columns:minmax(0,1fr); }
[data-slot="alert-dialog-title"], [data-slot="alert-dialog-description"] { overflow-wrap:anywhere; }
[data-slot="alert-dialog-footer"] { flex-wrap:wrap; }
@media (max-width:640px) { [data-slot="alert-dialog-content"] { width:calc(100% - 24px); padding:var(--s-6); } }

}
